-- Profil açıklamalarını ve uzmanlıkları düzeltir.
--
-- 1) Dilbilgisi: cümleler birinci tekil şahısken ikinci yüklem üçüncü şahıs kalmıştı
--    ("Antalya merkezli çalışıyor, verdiğim teslim tarihine sadık kalıyorum").
-- 2) Vitrin satıcılarının uzmanlıkları katalogdan seçiliyordu, ilanlarıyla ilgisi
--    olmayabiliyordu; artık gerçekten sattıkları işlerden (ilanlarının alt kategorileri)
--    geliyor ve açıklama da onları anıyor.
--
-- Fotoğrafa dokunulmaz: COALESCE yalnızca fotoğrafı olmayan profili doldurur, çekilmiş
-- gerçek portreler yerinde kalır.

UPDATE "users"
SET "bio" = replace(
      replace("bio", 'yaşıyor, tüm', 'yaşıyorum, tüm'),
      'merkezli çalışıyor, verdiğim',
      'merkezli çalışıyorum, verdiğim'
    ),
    "updatedAt" = now()
WHERE "synthetic" AND "bio" IS NOT NULL;

UPDATE "users" AS u SET
  "city" = v.city,
  "age" = v.age,
  "skills" = v.skills,
  "image" = COALESCE(u."image", v.image),
  "bio" = v.bio,
  "synthetic" = true,
  "updatedAt" = now()
FROM (VALUES
  ('elif@profestia.dev', 'Gaziantep', 42, ARRAY['Sosyal Medya Yönetimi', 'Video & Sunum Müziği']::text[], '/api/avatar/k-elif-k-elif', 'Gaziantep''te yaşıyorum ve 7 yıldır Sosyal Medya Uzmanı olarak proje üretiyorum. Sosyal Medya Yönetimi ve Video & Sunum Müziği başta olmak üzere işin tamamını uçtan uca yönetiyorum.'),
